const RELEASE='neptune-production-cockpit-ui-20260815-v120';
const API='/api/admin/media-catalog-v98/';
let ctx=null;
let view='overview';
let cityFilter='';
let searchText='';
let passageFilter='upcoming';
let drawer=null;
let loading=false;
let supplierDraft=null;
let formatDraft=null;

document.body.dataset.productionCockpitV120=RELEASE;
boot();

function boot(){
  window.addEventListener('neptune:production-v120',activate);
  window.addEventListener('hashchange',()=>{if(active())activate();else closeDrawer(false);});
  const app=document.getElementById('app');
  if(app)new MutationObserver(()=>{if(active()&&!app.hidden&&!document.querySelector('.p120')&&!loading)setTimeout(activate,0);}).observe(app,{attributes:true,attributeFilter:['hidden']});
  new MutationObserver(()=>repairFinanceCopy()).observe(document.body,{subtree:true,childList:true});
  repairFinanceCopy();
  if(active())activate();
}

function active(){return location.pathname.includes('/studio/advanced')&&decodeURIComponent(location.hash.slice(1)).trim()==='production';}

async function activate(){
  if(!active())return;
  const app=document.getElementById('app'),content=document.getElementById('content');
  if(!content||app?.hidden)return;
  document.getElementById('title').textContent='Production';
  if(!ctx){
    loading=true;
    content.innerHTML='<div class="p120-loading">Chargement du réseau de production…</div>';
    try{ctx=await productionAction('production_context');}
    catch(error){content.innerHTML=`<div class="p120-empty"><div><strong>Impossible de charger Production.</strong><p>${esc(errorText(error.message))}</p><button class="p120-btn" type="button" data-p120="refresh">Réessayer</button></div></div>`;bindRoot(content);loading=false;return;}
    loading=false;
  }
  render();
}

function render(){
  if(!active())return;
  const content=document.getElementById('content');if(!content||!ctx)return;
  document.getElementById('title').textContent='Production';
  const kpis=metrics();
  content.dataset.productionV120='ready';
  content.innerHTML=`<div class="p120" data-release="${RELEASE}">
    <header class="p120-hero"><div><p class="p120-eyebrow">RÉSEAU DE PRODUCTION</p><h2>Production</h2><p>Qui produit, où, quel format, à quel coût et quels règlements restent à effectuer : tout est regroupé ici sans reconstruire mentalement le Catalogue Media.</p></div><div class="p120-actions"><button class="p120-btn secondary" type="button" data-p120="refresh">Actualiser</button><button class="p120-btn secondary" type="button" data-p120="new-format">+ Nouveau format</button><button class="p120-btn" type="button" data-p120="new-supplier">+ Nouveau fournisseur</button></div></header>
    <section class="p120-kpis">${kpi(kpis.suppliers,'Fournisseurs actifs','réseau disponible')}${kpi(kpis.cities,'Villes couvertes','prestations actives')}${kpi(kpis.formats,'Formats compatibles','production configurée')}${kpi(kpis.upcoming,'Passages à venir','rattachés à un fournisseur')}${kpi(money(kpis.due),'À payer','fournisseurs')}</section>
    <section class="p120-toolbar"><div class="p120-city-filter"><button class="p120-chip ${!cityFilter?'active':''}" data-p120="city" data-city="">Toutes les villes</button>${(ctx.cities||[]).filter(c=>c.active!==false).map(c=>`<button class="p120-chip ${cityFilter===c.id?'active':''}" data-p120="city" data-city="${esc(c.id)}">${esc(c.name)}</button>`).join('')}</div><input class="p120-search" id="p120Search" value="${esc(searchText)}" placeholder="Rechercher fournisseur, format, client…"></section>
    <nav class="p120-tabs" aria-label="Production"><button class="p120-tab ${view==='overview'?'active':''}" data-p120="view" data-view="overview">Vue d’ensemble</button><button class="p120-tab ${view==='suppliers'?'active':''}" data-p120="view" data-view="suppliers">Fournisseurs</button><button class="p120-tab ${view==='services'?'active':''}" data-p120="view" data-view="services">Prestations & tarifs</button><button class="p120-tab ${view==='passages'?'active':''}" data-p120="view" data-view="passages">Passages & paiements</button><button class="p120-tab ${view==='formats'?'active':''}" data-p120="view" data-view="formats">Formats & préparation</button></nav>
    <main class="p120-view">${renderView()}</main>${drawerMarkup()}
  </div>`;
  bindRoot(content);
  hydrateB64(content);
}

function renderView(){return({overview:overviewView,suppliers:suppliersView,services:servicesView,passages:passagesView,formats:formatsView}[view]||overviewView)();}

function overviewView(){
  const suppliers=filteredSuppliers().slice(0,6),missingRates=(ctx.services||[]).filter(s=>s.active!==false&&ratesForService(s.id).length===0).length,unassigned=filteredPassages().filter(p=>!p.supplierId&&!['completed'].includes(p.status)).length,formatsWithoutCards=(ctx.formats||[]).filter(f=>f.active!==false&&cardsForFormat(f.id).length===0).length;
  return `<div class="p120-scroll"><div class="p120-section"><div class="p120-section-head"><div><p class="p120-eyebrow">EN UN COUP D’ŒIL</p><h3>Réseau de fournisseurs</h3><p>Une carte résume la couverture, les formats, les prochains passages et les règlements.</p></div><button class="p120-btn secondary" type="button" data-p120="view" data-view="suppliers">Voir tous</button></div><div class="p120-grid">${suppliers.length?suppliers.map(supplierCard).join(''):empty('Aucun fournisseur ne correspond aux filtres.')}</div></div><div class="p120-section" style="margin-top:14px"><div class="p120-section-head"><div><p class="p120-eyebrow">POINTS À TRAITER</p><h3>Ce qui mérite votre attention</h3></div></div><div class="p120-alert-grid">${alertCard('€',duePassages().length,'Paiements à effectuer',money(dueTotal()))}${alertCard('!',missingRates,'Prestations sans tarif','À compléter avant un nouveau passage')}${alertCard('↔',unassigned,'Passages non rattachés','Choisir fournisseur et tarif')}${formatsWithoutCards?alertCard('▧',formatsWithoutCards,'Formats sans préparation','Ajouter les cards de préparation'):''}</div></div></div>`;
}

function suppliersView(){const items=filteredSuppliers();return `<div class="p120-scroll"><div class="p120-section"><div class="p120-section-head"><div><p class="p120-eyebrow">FOURNISSEURS</p><h3>${items.length} partenaire${items.length>1?'s':''}</h3><p>Ouvrez une fiche pour gérer ses villes, formats, tarifs, passages et règlements.</p></div><button class="p120-btn" type="button" data-p120="new-supplier">+ Nouveau fournisseur</button></div><div class="p120-grid">${items.length?items.map(supplierCard).join(''):empty('Aucun fournisseur ne correspond aux filtres.')}</div></div></div>`;}

function servicesView(){
  const items=filteredServices();
  return `<div class="p120-scroll"><div class="p120-section"><div class="p120-section-head"><div><p class="p120-eyebrow">VILLE × FOURNISSEUR × FORMAT</p><h3>Prestations et tarifs négociés</h3><p>Chaque ligne représente une capacité réelle de production. Les tarifs sont attachés à la durée réservée.</p></div></div><div class="p120-table">${items.length?items.map(serviceRow).join(''):empty('Aucune prestation ne correspond aux filtres.')}</div></div></div>`;
}

function passagesView(){
  const filters=[['upcoming','À venir'],['filmed','Réalisés'],['due','À payer'],['paid','Payés'],['all','Tous']],items=passagesForFilter();
  return `<div class="p120-scroll"><div class="p120-section"><div class="p120-section-head"><div><p class="p120-eyebrow">PASSAGES & RÈGLEMENTS</p><h3>Du tournage au paiement fournisseur</h3><p>Le coût affiché est le tarif fournisseur figé au moment du rattachement du passage.</p></div><div class="p120-inline-actions">${filters.map(([id,label])=>`<button class="p120-subtab ${passageFilter===id?'active':''}" data-p120="passage-filter" data-filter="${id}">${label}</button>`).join('')}</div></div><div class="p120-table">${items.length?items.map(passageRow).join(''):empty('Aucun passage dans cette vue.')}</div></div></div>`;
}

function formatsView(){const formats=filteredFormats();return `<div class="p120-scroll"><div class="p120-section"><div class="p120-section-head"><div><p class="p120-eyebrow">FORMATS & PRÉPARATION</p><h3>Formats produits par le réseau</h3><p>Les cards de préparation appartiennent au format. Chaque nouveau format peut ensuite être affecté aux fournisseurs compatibles.</p></div><button class="p120-btn" type="button" data-p120="new-format">+ Nouveau format</button></div><div class="p120-format-grid">${formats.length?formats.map(formatCard).join(''):empty('Aucun format ne correspond aux filtres.')}</div></div></div>`;}

function supplierCard(s){
  const services=servicesForSupplier(s.id).filter(cityMatch),cities=unique(services.map(x=>x.cityName)),formats=unique(services.map(x=>x.formatName)),passages=passagesForSupplier(s.id),upcoming=passages.filter(isUpcoming).length,due=passages.filter(p=>p.supplierPaymentStatus==='due').reduce((sum,p)=>sum+Number(p.supplierPaymentAmount||p.supplierGrossCents||0),0),rates=services.reduce((sum,service)=>sum+ratesForService(service.id).length,0);
  return `<button class="p120-card" type="button" data-p120="open-supplier" data-id="${esc(s.id)}"><div class="p120-card-head"><div><span class="p120-status ${s.active===false?'warning':''}">${s.active===false?'Inactif':'Actif'}</span><h4 style="margin-top:7px">${esc(s.name)}</h4><p>${esc(s.legalName||s.email||'Fournisseur Neptune')}</p></div><span aria-hidden="true">→</span></div><div class="p120-badges">${cities.slice(0,3).map(x=>`<span class="p120-badge">${esc(x)}</span>`).join('')||'<span class="p120-badge">Ville à rattacher</span>'}${formats.slice(0,3).map(x=>`<span class="p120-badge">${esc(x)}</span>`).join('')}</div><div class="p120-card-metrics"><div><small>Prestations</small><strong>${services.length}</strong></div><div><small>Tarifs</small><strong>${rates}</strong></div><div><small>À venir</small><strong>${upcoming}</strong></div></div><div class="p120-card-head"><p>${due?`À régler : ${money(due)}`:'Aucun règlement en attente'}</p><strong>${esc(paymentMethodLabel(s.payment?.paymentMethod))}</strong></div></button>`;
}

function serviceRow(s){const rates=ratesForService(s.id);return `<article class="p120-row p120-row--service"><div class="p120-row-main"><strong>${esc(s.cityName)} · ${esc(s.supplierName)}</strong><small>${esc(s.formatName)}${s.preparationUrl?' · préparation configurée':''}</small></div><div><strong>${rates.length} tarif${rates.length>1?'s':''}</strong><div class="p120-rate-chips">${rates.slice(0,4).map(r=>`<span class="p120-rate-chip">${esc(r.label)} · ${money(r.netCents)} HT</span>`).join('')||'<span class="p120-status warning">Tarif manquant</span>'}</div></div><div><span>${esc(s.notes||'Aucune note opérationnelle')}</span></div><div class="p120-inline-actions"><button class="p120-btn secondary" type="button" data-p120="open-supplier" data-id="${esc(s.supplierId)}" data-tab="services">Gérer</button></div></article>`;}

function passageRow(p){
  const missing=!p.supplierId,status=p.supplierPaymentStatus==='paid'?'paid':p.supplierPaymentStatus==='due'?'due':missing?'warning':'';
  return `<article class="p120-row"><div class="p120-row-main"><strong>${esc(p.fullName||p.company||p.email||p.title)}</strong><small>${esc(p.company||p.email||'')} · ${esc(p.format||p.formatName||'Format à préciser')}</small></div><div><strong>${p.filmingAt?dateTime(p.filmingAt):'Date à fixer'}</strong><span>${missing?'Fournisseur non rattaché':`${esc(p.cityName)} · ${esc(p.supplierName)}`}</span></div><div><strong>${missing?'—':money(p.supplierGrossCents)}</strong><span>${missing?'Coût fournisseur manquant':`${esc(p.rateLabel||durationLabel(p.durationMinutes))} · ${money(p.supplierNetCents)} HT`}</span></div><div><span class="p120-status ${status}">${p.supplierPaymentStatus==='paid'?'Payé':p.supplierPaymentStatus==='due'?'À payer':missing?'À rattacher':'À venir'}</span>${p.supplierPaymentDueAt?`<span>${dateOnly(p.supplierPaymentDueAt)}</span>`:''}</div><div class="p120-inline-actions">${missing?`<button class="p120-btn secondary" type="button" data-p120="assign-passage" data-id="${esc(p.id)}">Rattacher</button>`:''}${p.supplierPaymentStatus==='due'?`<button class="p120-btn" type="button" data-p120="pay" data-id="${esc(p.supplierPaymentId)}">Marquer payé</button>`:''}</div></article>`;
}

function formatCard(f){const cards=cardsForFormat(f.id),services=(ctx.services||[]).filter(s=>s.active!==false&&s.formatId===f.id),cities=unique(services.map(s=>s.cityName)),suppliers=unique(services.map(s=>s.supplierName));return `<article class="p120-card p120-format"><div class="p120-format-media">${image(f.image,f.name)}</div><div class="p120-format-body"><div class="p120-card-head"><div><p class="p120-eyebrow">${esc(f.concept||'FORMAT')}</p><h4>${esc(f.name)}</h4><p>${esc(f.shootDurationLabel||f.durationLabel||'Durée à préciser')} · ${esc(f.totalDurationLabel||'allocation à préciser')}</p></div><span class="p120-status ${f.active===false?'warning':''}">${f.active===false?'Masqué':'Actif'}</span></div><div class="p120-prep-mini">${cards.slice(0,5).map(c=>`<span>${esc(c.label)}</span>`).join('')||'<span>Aucune card préparation</span>'}</div><div class="p120-card-metrics"><div><small>Cards</small><strong>${cards.length}</strong></div><div><small>Fournisseurs</small><strong>${suppliers.length}</strong></div><div><small>Villes</small><strong>${cities.length}</strong></div></div><button class="p120-btn secondary" type="button" data-p120="open-format" data-id="${esc(f.id)}">Gérer le format</button></div></article>`;}

function drawerMarkup(){if(!drawer)return'';return `<div class="p120-drawer-backdrop" data-p120="close-drawer"></div>${drawer.type==='supplier'?supplierDrawer():drawer.type==='format'?formatDrawer():drawer.type==='passage'?passageDrawer():drawer.type==='supplier-new'?supplierWizard():drawer.type==='format-new'?formatWizard():''}`;}

function supplierDrawer(){
  const s=supplierById(drawer.id);if(!s)return'';const tab=drawer.tab||'overview';
  return `<aside class="p120-drawer" aria-label="Fiche fournisseur"><header class="p120-drawer-head"><div><p class="p120-eyebrow">FOURNISSEUR</p><h3>${esc(s.name)}</h3><p>${unique(servicesForSupplier(s.id).map(x=>x.cityName)).join(' · ')||'Aucune ville rattachée'}</p></div><button class="p120-close" type="button" data-p120="close-drawer" aria-label="Fermer">×</button></header><nav class="p120-drawer-tabs">${drawerTab('overview','Aperçu',tab)}${drawerTab('services','Prestations & tarifs',tab)}${drawerTab('passages','Passages',tab)}${drawerTab('payments','Paiements',tab)}${drawerTab('info','Informations',tab)}</nav><div class="p120-drawer-body">${supplierDrawerBody(s,tab)}</div><footer class="p120-drawer-foot"><button class="p120-btn secondary" type="button" data-p120="close-drawer">Fermer</button></footer></aside>`;
}

function supplierDrawerBody(s,tab){
  const services=servicesForSupplier(s.id),passages=passagesForSupplier(s.id),due=passages.filter(p=>p.supplierPaymentStatus==='due');
  if(tab==='overview')return `<div class="p120-section"><div class="p120-kpis" style="grid-template-columns:repeat(3,minmax(0,1fr))">${kpi(services.length,'Prestations','ville × format')}${kpi(services.reduce((n,x)=>n+ratesForService(x.id).length,0),'Tarifs','négociés')}${kpi(money(due.reduce((n,p)=>n+Number(p.supplierPaymentAmount||0),0)),'À payer','fournisseur')}</div><div class="p120-help"><strong>Lecture :</strong> un fournisseur peut travailler dans plusieurs villes et produire plusieurs formats. Chaque couple ville + format possède ses propres durées et coûts.</div><div class="p120-section-head"><div><h3>Formats compatibles</h3></div><button class="p120-btn secondary" type="button" data-p120="drawer-tab" data-tab="services">Gérer</button></div>${services.length?services.slice(0,5).map(serviceMini).join(''):empty('Aucune prestation configurée.')}</div>`;
  if(tab==='services')return supplierServicesBody(s,services);
  if(tab==='passages')return `<div class="p120-table">${passages.length?passages.map(passageDrawerRow).join(''):empty('Aucun passage rattaché à ce fournisseur.')}</div>`;
  if(tab==='payments')return `<div class="p120-section"><p class="p120-finance-note">Mode de règlement : <strong>${esc(paymentMethodLabel(s.payment?.paymentMethod))}</strong>${s.payment?.paymentTermsDays?` · ${s.payment.paymentTermsDays} jour(s)`:''}${s.payment?.paymentUrl?` · <a href="${esc(s.payment.paymentUrl)}" target="_blank" rel="noopener">ouvrir le lien de règlement</a>`:''}</p><div class="p120-table">${passages.filter(p=>p.supplierPaymentStatus).length?passages.filter(p=>p.supplierPaymentStatus).map(paymentDrawerRow).join(''):empty('Aucun règlement créé pour ce fournisseur.')}</div></div>`;
  return supplierInfoForm(s);
}

function supplierServicesBody(s,services){return `<div class="p120-section"><div class="p120-inline-actions"><button class="p120-btn" type="button" data-p120="add-service">+ Ajouter ville / format</button></div>${drawer.sub==='service-add'?serviceForm({supplierId:s.id}):''}${services.length?services.map(serviceDetail).join(''):empty('Aucune prestation. Ajoutez une ville et un format compatible.')}${drawer.rateServiceId?rateForm(drawer.rateServiceId):''}</div>`;}
function serviceMini(service){const rates=ratesForService(service.id);return `<article class="p120-service-card"><div class="p120-service-head"><div><strong>${esc(service.cityName)} · ${esc(service.formatName)}</strong><span>${rates.length} tarif${rates.length>1?'s':''}</span></div></div><div class="p120-rate-chips">${rates.slice(0,4).map(r=>`<span class="p120-rate-chip">${esc(r.label)} · ${money(r.netCents)} HT</span>`).join('')}</div></article>`;}
function serviceDetail(service){const rates=ratesForService(service.id);return `<article class="p120-service-card"><div class="p120-service-head"><div><strong>${esc(service.cityName)} · ${esc(service.formatName)}</strong><span>${esc(service.preparationUrl||'Aucun lien de préparation spécifique')}</span></div><div class="p120-inline-actions"><button class="p120-btn secondary" type="button" data-p120="add-rate" data-service="${esc(service.id)}">+ Tarif</button><button class="p120-btn danger" type="button" data-p120="archive-service" data-id="${esc(service.id)}">Désactiver</button></div></div><div class="p120-rate-list">${rates.length?rates.map(r=>`<div class="p120-rate-row"><div><b>${esc(r.label)}</b><span>${durationLabel(r.durationMinutes)}</span></div><strong>${money(r.netCents)} HT</strong><button class="p120-btn danger" type="button" data-p120="archive-rate" data-id="${esc(r.id)}">×</button></div>`).join(''):'<span class="p120-status warning">Ajoutez au moins un tarif négocié</span>'}</div></article>`;}

function supplierInfoForm(s){const p=s.payment||{};return `<form class="p120-form" data-p120-form="supplier-info"><input type="hidden" name="supplierId" value="${esc(s.id)}"><fieldset class="p120-fieldset"><legend>Identité</legend><div class="p120-form-grid"><label class="p120-field"><span>Nom *</span><input name="name" required value="${esc(s.name)}"></label><label class="p120-field"><span>E-mail opérationnel</span><input name="email" type="email" value="${esc(s.email||'')}"></label><label class="p120-field wide"><span>Raison sociale</span><input name="legalName" value="${esc(s.legalName||'')}"></label><label class="p120-field wide"><span>Notes internes</span><textarea name="notes">${esc(s.notes||'')}</textarea></label></div></fieldset><fieldset class="p120-fieldset"><legend>Règlement fournisseur</legend><div class="p120-form-grid"><label class="p120-field"><span>Mode</span><select name="paymentMethod">${paymentOptions(p.paymentMethod)}</select></label><label class="p120-field"><span>Échéance habituelle</span><select name="paymentTermsDays">${[0,7,15,30,45,60].map(n=>`<option value="${n}" ${Number(p.paymentTermsDays||0)===n?'selected':''}>${n?n+' jours':'À réception'}</option>`).join('')}</select></label><label class="p120-field wide"><span>Lien de règlement fournisseur</span><input name="paymentUrl" type="url" value="${esc(p.paymentUrl||'')}" placeholder="https://…"><small>Ce lien est interne à Neptune. Il n’est jamais confondu avec les liens Stripe payés par le client.</small></label><label class="p120-field"><span>E-mail facturation</span><input name="billingEmail" type="email" value="${esc(p.billingEmail||s.email||'')}"></label><label class="p120-field wide"><span>Instructions de règlement</span><textarea name="paymentNotes">${esc(p.paymentNotes||'')}</textarea></label></div></fieldset><div class="p120-inline-actions"><button class="p120-btn" type="submit">Enregistrer</button></div></form>`;}

function serviceForm(fixed={}){const cities=(ctx.cities||[]).filter(c=>c.active!==false),suppliers=(ctx.suppliers||[]).filter(s=>s.active!==false),formats=(ctx.formats||[]).filter(f=>f.active!==false);return `<form class="p120-form" data-p120-form="service-add"><input type="hidden" name="fixedSupplierId" value="${esc(fixed.supplierId||'')}"><input type="hidden" name="fixedFormatId" value="${esc(fixed.formatId||'')}"><fieldset class="p120-fieldset"><legend>Nouvelle prestation</legend><div class="p120-form-grid"><label class="p120-field"><span>Ville</span><select name="cityId" required><option value="">Choisir…</option>${cities.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label>${fixed.supplierId?'':`<label class="p120-field"><span>Fournisseur</span><select name="supplierId" required><option value="">Choisir…</option>${suppliers.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label>`}${fixed.formatId?'':`<label class="p120-field"><span>Format compatible</span><select name="formatId" required><option value="">Choisir…</option>${formats.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select></label>`}<label class="p120-field wide"><span>Lien préparation spécifique</span><input name="preparationUrl" type="url" placeholder="https://…"></label></div><div class="p120-inline-actions"><button class="p120-btn secondary" type="button" data-p120="cancel-sub">Annuler</button><button class="p120-btn" type="submit">Ajouter la prestation</button></div></fieldset></form>`;}

function rateForm(serviceId){const options=ctx.durationOptions||[];return `<form class="p120-form" data-p120-form="rate-add"><input type="hidden" name="serviceId" value="${esc(serviceId)}"><fieldset class="p120-fieldset"><legend>Nouveau tarif négocié</legend><div class="p120-form-grid"><label class="p120-field"><span>Durée réservée</span><select name="durationMinutes" required><option value="">Choisir…</option>${options.map(o=>`<option value="${o.minutes}">${esc(o.label)}</option>`).join('')}</select></label><label class="p120-field"><span>Unité</span><select name="unitCode">${(ctx.rateUnits||[]).map(u=>`<option value="${esc(u.code)}">${esc(u.label)}</option>`).join('')}</select></label><label class="p120-field"><span>Coût fournisseur HT (€)</span><input name="net" type="number" min="0" step=".01" required></label><label class="p120-field"><span>TVA (%)</span><input name="vat" type="number" min="0" max="100" step=".1" value="20"></label></div><div class="p120-inline-actions"><button class="p120-btn secondary" type="button" data-p120="cancel-rate">Annuler</button><button class="p120-btn" type="submit">Ajouter le tarif</button></div></fieldset></form>`;}

function formatDrawer(){const f=formatById(drawer.id);if(!f)return'';const tab=drawer.tab||'cards';return `<aside class="p120-drawer" aria-label="Fiche format"><header class="p120-drawer-head"><div><p class="p120-eyebrow">FORMAT</p><h3>${esc(f.name)}</h3><p>${esc(f.concept||'Concept à préciser')}</p></div><button class="p120-close" type="button" data-p120="close-drawer">×</button></header><nav class="p120-drawer-tabs">${drawerTab('cards','Cards préparation',tab)}${drawerTab('suppliers','Fournisseurs compatibles',tab)}${drawerTab('info','Informations',tab)}</nav><div class="p120-drawer-body">${formatDrawerBody(f,tab)}</div><footer class="p120-drawer-foot"><button class="p120-btn secondary" type="button" data-p120="close-drawer">Fermer</button></footer></aside>`;}

function formatDrawerBody(f,tab){if(tab==='cards')return prepCardsBody(f);if(tab==='suppliers')return formatSuppliersBody(f);return formatInfoForm(f);}
function prepCardsBody(f){const cards=cardsForFormat(f.id);return `<div class="p120-section"><div class="p120-help"><strong>Règle :</strong> ces cards appartiennent au format ${esc(f.name)}. Elles sont automatiquement disponibles sur ses offres, quel que soit le fournisseur compatible.</div><div class="p120-inline-actions"><button class="p120-btn" type="button" data-p120="new-card">+ Ajouter une card</button></div>${drawer.cardEdit?prepCardForm(f,drawer.cardEdit):''}${cards.length?cards.map(c=>`<article class="p120-card-editor">${prepImage(c)}<div><h5>${esc(c.label)}</h5><p>${esc(c.description||'Aucune description')}</p></div><div class="p120-inline-actions"><button class="p120-btn secondary" type="button" data-p120="edit-card" data-id="${esc(c.id)}">Modifier</button><button class="p120-btn danger" type="button" data-p120="archive-card" data-id="${esc(c.id)}">Retirer</button></div></article>`).join(''):empty('Aucune card de préparation. Ajoutez les choix nécessaires à ce format.')}</div>`;}
function prepCardForm(f,c={}){const target=`p120PrepImage${String(c.id||'new').replace(/[^a-z0-9]/giu,'')}`;return `<form class="p120-form" data-p120-form="prep-card"><input type="hidden" name="id" value="${esc(c.id||'')}"><input type="hidden" name="formatId" value="${esc(f.id)}"><fieldset class="p120-fieldset"><legend>${c.id?'Modifier':'Nouvelle'} card</legend><div class="p120-form-grid"><label class="p120-field"><span>Nom affiché *</span><input name="label" required value="${esc(c.label||'')}"></label><label class="p120-field"><span>Ordre</span><input name="publicOrder" type="number" value="${Number(c.publicOrder||100)}"></label><label class="p120-field wide"><span>Description client</span><textarea name="description">${esc(c.description||'')}</textarea></label><label class="p120-field wide"><span>Visuel</span><input id="${target}" name="imageUrl" value="${esc(c.imageUrl||c.image||'')}" placeholder="/media/catalog-v98/…"><small><input type="file" accept="image/jpeg,image/png,image/webp" data-p120-upload-for="${target}"></small></label></div><div class="p120-inline-actions"><button class="p120-btn secondary" type="button" data-p120="cancel-card">Annuler</button><button class="p120-btn" type="submit">Enregistrer la card</button></div></fieldset></form>`;}
function formatSuppliersBody(f){const services=(ctx.services||[]).filter(s=>s.active!==false&&s.formatId===f.id);return `<div class="p120-section"><div class="p120-inline-actions"><button class="p120-btn" type="button" data-p120="add-service">+ Affecter à un fournisseur</button></div>${drawer.sub==='service-add'?serviceForm({formatId:f.id}):''}${services.length?services.map(serviceDetail).join(''):empty('Ce format n’est encore produit par aucun fournisseur.')}</div>`;}
function formatInfoForm(f){const durations=ctx.durationOptions||[];return `<form class="p120-form" data-p120-form="format-info"><input type="hidden" name="formatId" value="${esc(f.id)}"><div class="p120-form-grid"><label class="p120-field"><span>Nom public *</span><input name="name" required value="${esc(f.name)}"></label><label class="p120-field"><span>Concept</span><select name="conceptId">${(ctx.concepts||[]).filter(c=>c.active!==false||c.id===f.conceptId).map(c=>`<option value="${esc(c.id)}" ${c.id===f.conceptId?'selected':''}>${esc(c.label)}</option>`).join('')}</select></label><label class="p120-field"><span>Durée tournage</span><select name="shootMinutes">${durations.map(o=>`<option value="${o.minutes}" ${Number(f.shootMinutes)===Number(o.minutes)?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label><label class="p120-field"><span>Durée totale allouée</span><select name="totalMinutes">${durations.map(o=>`<option value="${o.minutes}" ${Number(f.totalMinutes)===Number(o.minutes)?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label><label class="p120-field wide"><span>Description</span><textarea name="description">${esc(f.description||'')}</textarea></label><label class="p120-field wide"><span>Visuel</span><input id="p120FormatImageEdit" name="imageUrl" value="${esc(f.image||'')}"><small><input type="file" accept="image/jpeg,image/png,image/webp" data-p120-upload-for="p120FormatImageEdit"></small></label></div><div class="p120-inline-actions"><button class="p120-btn" type="submit">Enregistrer le format</button></div></form>`;}

function passageDrawer(){const p=passageById(drawer.id);if(!p)return'';const services=matchingServicesForPassage(p),options=[];for(const service of services)for(const rate of ratesForService(service.id))options.push({service,rate});return `<aside class="p120-drawer" aria-label="Rattacher un passage"><header class="p120-drawer-head"><div><p class="p120-eyebrow">PASSAGE</p><h3>${esc(p.fullName||p.company||p.title)}</h3><p>${esc(p.format||'Format')} · ${p.filmingAt?dateTime(p.filmingAt):'date à fixer'}</p></div><button class="p120-close" type="button" data-p120="close-drawer">×</button></header><div></div><div class="p120-drawer-body"><form class="p120-form" data-p120-form="passage-assign"><input type="hidden" name="orderId" value="${esc(p.id)}"><div class="p120-help">Choisissez la prestation réellement utilisée. Neptune figera son coût pour ce passage ; une hausse tarifaire future ne modifiera pas ce dossier.</div><label class="p120-field"><span>Prestation & tarif fournisseur</span><select name="rateId" required><option value="">Choisir…</option>${options.map(({service,rate})=>`<option value="${esc(rate.id)}">${esc(service.cityName)} · ${esc(service.supplierName)} · ${esc(rate.label)} · ${money(rate.netCents)} HT</option>`).join('')}</select></label>${options.length?'':'<div class="p120-empty"><div><strong>Aucun tarif compatible.</strong><p>Ajoutez d’abord le format au fournisseur dans « Prestations & tarifs ».</p></div></div>'}<button class="p120-btn" type="submit" ${options.length?'':'disabled'}>Rattacher et figer le coût</button></form></div><footer class="p120-drawer-foot"><button class="p120-btn secondary" type="button" data-p120="close-drawer">Annuler</button></footer></aside>`;}

function supplierWizard(){const d=supplierDraft||newSupplierDraft(),labels=['Identité','Villes & formats','Tarifs','Validation'];return `<aside class="p120-drawer" aria-label="Nouveau fournisseur"><header class="p120-drawer-head"><div><p class="p120-eyebrow">NOUVEAU FOURNISSEUR</p><h3>Créer un partenaire</h3><p>Le fournisseur, ses capacités et ses premiers tarifs dans un seul workflow.</p></div><button class="p120-close" type="button" data-p120="close-drawer">×</button></header><div class="p120-wizard-progress" style="grid-template-columns:repeat(4,minmax(0,1fr))">${labels.map((x,i)=>`<span class="${i===d.step?'active':i<d.step?'done':''}">${i<d.step?'✓ ':''}${esc(x)}</span>`).join('')}</div><div class="p120-drawer-body">${supplierWizardStep(d)}</div><footer class="p120-drawer-foot"><button class="p120-btn secondary" type="button" data-p120="supplier-back" ${d.step===0?'disabled':''}>Retour</button><button class="p120-btn" type="button" data-p120="supplier-next">${d.step===3?'Créer le fournisseur':'Continuer'}</button></footer></aside>`;}
function supplierWizardStep(d){
  if(d.step===0)return `<div class="p120-form"><div class="p120-form-grid"><label class="p120-field"><span>Nom *</span><input id="p120DraftSupplierName" value="${esc(d.name)}"></label><label class="p120-field"><span>E-mail</span><input id="p120DraftSupplierEmail" type="email" value="${esc(d.email)}"></label><label class="p120-field wide"><span>Raison sociale</span><input id="p120DraftSupplierLegal" value="${esc(d.legalName)}"></label><label class="p120-field"><span>Mode de règlement</span><select id="p120DraftSupplierMethod">${paymentOptions(d.paymentMethod)}</select></label><label class="p120-field"><span>Échéance</span><select id="p120DraftSupplierTerms">${[0,7,15,30,45,60].map(n=>`<option value="${n}" ${d.paymentTermsDays===n?'selected':''}>${n?n+' jours':'À réception'}</option>`).join('')}</select></label><label class="p120-field wide"><span>Lien de règlement</span><input id="p120DraftSupplierPaymentUrl" type="url" value="${esc(d.paymentUrl)}" placeholder="https://…"></label></div></div>`;
  if(d.step===1)return draftCapabilities(d,'supplier');
  if(d.step===2)return draftRates(d,'supplier');
  return `<div class="p120-review"><article><small>Fournisseur</small><b>${esc(d.name)} · ${esc(d.email||'sans e-mail')}</b></article><article><small>Prestations</small><b>${d.capabilities.length} ville × format</b></article><article><small>Tarifs initiaux</small><b>${d.capabilities.reduce((n,c)=>n+c.rates.length,0)} tarif(s)</b></article><article><small>Règlement</small><b>${esc(paymentMethodLabel(d.paymentMethod))}${d.paymentTermsDays?` · ${d.paymentTermsDays} jours`:''}</b></article></div>`;
}

function formatWizard(){const d=formatDraft||newFormatDraft(),labels=['Format','Cards préparation','Fournisseurs','Tarifs','Validation'];return `<aside class="p120-drawer" aria-label="Nouveau format"><header class="p120-drawer-head"><div><p class="p120-eyebrow">NOUVEAU FORMAT</p><h3>Créer puis distribuer le format</h3><p>Le format, ses cards de préparation et les fournisseurs capables de le produire.</p></div><button class="p120-close" type="button" data-p120="close-drawer">×</button></header><div class="p120-wizard-progress">${labels.map((x,i)=>`<span class="${i===d.step?'active':i<d.step?'done':''}">${i<d.step?'✓ ':''}${esc(x)}</span>`).join('')}</div><div class="p120-drawer-body">${formatWizardStep(d)}</div><footer class="p120-drawer-foot"><button class="p120-btn secondary" type="button" data-p120="format-back" ${d.step===0?'disabled':''}>Retour</button><button class="p120-btn" type="button" data-p120="format-next">${d.step===4?'Créer le format':'Continuer'}</button></footer></aside>`;}
function formatWizardStep(d){
  if(d.step===0)return `<div class="p120-form"><div class="p120-form-grid"><label class="p120-field wide"><span>Nom du format *</span><input id="p120DraftFormatName" value="${esc(d.name)}" placeholder="Ex. Interview Expert"></label><label class="p120-field"><span>Concept</span><select id="p120DraftFormatConcept">${(ctx.concepts||[]).filter(c=>c.active!==false).map(c=>`<option value="${esc(c.id)}" ${d.conceptId===c.id?'selected':''}>${esc(c.label)}</option>`).join('')}<option value="__new" ${d.conceptId==='__new'?'selected':''}>+ Nouveau concept</option></select></label><label class="p120-field"><span>Nouveau concept</span><input id="p120DraftFormatNewConcept" value="${esc(d.newConcept)}" placeholder="Si sélectionné ci-contre"></label><label class="p120-field"><span>Durée tournage</span><select id="p120DraftFormatShoot">${durationOptions(d.shootMinutes)}</select></label><label class="p120-field"><span>Durée totale allouée</span><select id="p120DraftFormatTotal">${durationOptions(d.totalMinutes)}</select></label><label class="p120-field wide"><span>Visuel</span><input id="p120DraftFormatImage" value="${esc(d.imageUrl)}"><small><input type="file" accept="image/jpeg,image/png,image/webp" data-p120-upload-for="p120DraftFormatImage"></small></label><label class="p120-field wide"><span>Description</span><textarea id="p120DraftFormatDescription">${esc(d.description)}</textarea></label></div></div>`;
  if(d.step===1)return draftPreparationCards(d);
  if(d.step===2)return draftCapabilities(d,'format');
  if(d.step===3)return draftRates(d,'format');
  return `<div class="p120-review"><article><small>Format</small><b>${esc(d.name)} · ${durationLabel(d.shootMinutes)} tournage / ${durationLabel(d.totalMinutes)} allouées</b></article><article><small>Cards préparation</small><b>${d.cards.length} card(s) : ${esc(d.cards.map(c=>c.label).filter(Boolean).join(', ')||'aucune')}</b></article><article><small>Fournisseurs</small><b>${d.capabilities.length} affectation(s)</b></article><article><small>Tarifs initiaux</small><b>${d.capabilities.reduce((n,c)=>n+c.rates.length,0)} tarif(s)</b></article></div>`;
}

function draftPreparationCards(d){return `<div class="p120-section"><div class="p120-help">Ajoutez les choix que le client doit voir pour préparer ce format : Canapé, Chaise, Plateau, Bar, etc. HORS NORME utilise exactement ce même modèle.</div><button class="p120-btn secondary" type="button" data-p120="draft-add-card">+ Ajouter une card</button>${d.cards.map((c,i)=>`<article class="p120-draft-card"><div class="p120-draft-card-head"><b>Card ${i+1}</b><button class="p120-btn danger" type="button" data-p120="draft-remove-card" data-index="${i}">Retirer</button></div><div class="p120-form-grid"><label class="p120-field"><span>Nom</span><input data-draft-card-label="${i}" value="${esc(c.label)}"></label><label class="p120-field wide"><span>Description</span><input data-draft-card-description="${i}" value="${esc(c.description)}"></label><label class="p120-field wide"><span>Visuel</span><input id="p120DraftCardImage${i}" data-draft-card-image="${i}" value="${esc(c.imageUrl)}"><small><input type="file" accept="image/jpeg,image/png,image/webp" data-p120-upload-for="p120DraftCardImage${i}"></small></label></div></article>`).join('')||empty('Aucune card. Vous pouvez continuer si ce format ne nécessite aucun choix de préparation.')}</div>`;}

function draftCapabilities(d,kind){const cities=(ctx.cities||[]).filter(c=>c.active!==false),formats=(ctx.formats||[]).filter(f=>f.active!==false),suppliers=(ctx.suppliers||[]).filter(s=>s.active!==false);return `<div class="p120-section"><div class="p120-help">${kind==='supplier'?'Ajoutez chaque couple ville + format que ce fournisseur sait réellement produire.':'Choisissez chaque couple ville + fournisseur capable de produire ce nouveau format.'}</div>${d.capabilities.map((c,i)=>`<article class="p120-draft-card"><div class="p120-draft-card-head"><b>${kind==='supplier'?`${esc(cityName(c.cityId))} · ${esc(formatName(c.formatId))}`:`${esc(cityName(c.cityId))} · ${esc(supplierName(c.supplierId))}`}</b><button class="p120-btn danger" type="button" data-p120="draft-remove-cap" data-kind="${kind}" data-index="${i}">Retirer</button></div>${kind==='format'?`<label class="p120-field"><span>Lien préparation spécifique fournisseur</span><input data-draft-cap-prep="${i}" value="${esc(c.preparationUrl||'')}"></label>`:''}</article>`).join('')}${kind==='supplier'?`<fieldset class="p120-fieldset"><legend>Ajouter une capacité</legend><div class="p120-form-grid"><label class="p120-field"><span>Ville</span><select id="p120DraftCapCity"><option value="">Choisir…</option>${cities.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label class="p120-field"><span>Format</span><select id="p120DraftCapFormat"><option value="">Choisir…</option>${formats.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select></label></div><button class="p120-btn secondary" type="button" data-p120="draft-add-cap" data-kind="supplier">+ Ajouter</button></fieldset>`:`<fieldset class="p120-fieldset"><legend>Affecter le format</legend><div class="p120-form-grid"><label class="p120-field"><span>Ville</span><select id="p120DraftCapCity"><option value="">Choisir…</option>${cities.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label class="p120-field"><span>Fournisseur</span><select id="p120DraftCapSupplier"><option value="">Choisir…</option>${suppliers.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label></div><button class="p120-btn secondary" type="button" data-p120="draft-add-cap" data-kind="format">+ Affecter</button></fieldset>`}</div>`;}

function draftRates(d,kind){return `<div class="p120-section"><div class="p120-help">Renseignez les coûts négociés par durée. Vous pourrez en ajouter ou modifier d’autres ensuite depuis la fiche fournisseur.</div>${d.capabilities.map((c,ci)=>`<article class="p120-draft-card"><div class="p120-draft-card-head"><b>${kind==='supplier'?`${esc(cityName(c.cityId))} · ${esc(formatName(c.formatId))}`:`${esc(cityName(c.cityId))} · ${esc(supplierName(c.supplierId))}`}</b><button class="p120-btn secondary" type="button" data-p120="draft-add-rate" data-kind="${kind}" data-cap="${ci}">+ Tarif</button></div>${c.rates.map((r,ri)=>`<div class="p120-form-grid"><label class="p120-field"><span>Durée</span><select data-draft-rate-duration="${ci}:${ri}">${durationOptions(r.durationMinutes)}</select></label><label class="p120-field"><span>Coût HT (€)</span><input data-draft-rate-net="${ci}:${ri}" type="number" min="0" step=".01" value="${r.netCents?(r.netCents/100).toFixed(2):''}"></label><div class="p120-inline-actions"><button class="p120-btn danger" type="button" data-p120="draft-remove-rate" data-kind="${kind}" data-cap="${ci}" data-rate="${ri}">Retirer</button></div></div>`).join('')||'<span class="p120-status warning">Aucun tarif initial</span>'}</article>`).join('')||empty('Ajoutez d’abord une ville et un format/fournisseur à l’étape précédente.')}</div>`;}

function bindRoot(content){if(content.dataset.p120Bound==='1')return;content.dataset.p120Bound='1';content.addEventListener('click',handleClick);content.addEventListener('submit',handleSubmit);content.addEventListener('input',handleInput);content.addEventListener('change',handleChange);}

async function handleClick(event){
  const button=event.target.closest('[data-p120]');if(!button)return;const action=button.dataset.p120;
  if(action==='close-drawer'){closeDrawer();return;}
  if(action==='refresh'){await reload('Production actualisée.');return;}
  if(action==='view'){view=button.dataset.view;render();return;}
  if(action==='city'){cityFilter=button.dataset.city||'';render();return;}
  if(action==='passage-filter'){passageFilter=button.dataset.filter||'upcoming';render();return;}
  if(action==='open-supplier'){drawer={type:'supplier',id:button.dataset.id,tab:button.dataset.tab||'overview'};render();return;}
  if(action==='open-format'){drawer={type:'format',id:button.dataset.id,tab:'cards'};render();return;}
  if(action==='assign-passage'){drawer={type:'passage',id:button.dataset.id};render();return;}
  if(action==='new-supplier'){supplierDraft=newSupplierDraft();drawer={type:'supplier-new'};render();return;}
  if(action==='new-format'){formatDraft=newFormatDraft();drawer={type:'format-new'};render();return;}
  if(action==='drawer-tab'){drawer.tab=button.dataset.tab;drawer.sub='';drawer.rateServiceId='';drawer.cardEdit=null;render();return;}
  if(action==='add-service'){drawer.sub='service-add';drawer.rateServiceId='';render();return;}
  if(action==='cancel-sub'){drawer.sub='';render();return;}
  if(action==='add-rate'){drawer.rateServiceId=button.dataset.service;render();return;}
  if(action==='cancel-rate'){drawer.rateServiceId='';render();return;}
  if(action==='new-card'){drawer.cardEdit={active:true,publicOrder:(cardsForFormat(drawer.id).length+1)*10};render();return;}
  if(action==='edit-card'){drawer.cardEdit=(ctx.preparationCards||[]).find(c=>c.id===button.dataset.id)||null;render();return;}
  if(action==='cancel-card'){drawer.cardEdit=null;render();return;}
  if(action==='archive-card'){if(confirm('Retirer cette card de préparation de ce format ?'))await mutate(()=>productionAction('production_preparation_card_archive',{id:button.dataset.id}),'Card retirée.');return;}
  if(action==='archive-service'){if(confirm('Désactiver cette prestation ? Les offres actives peuvent empêcher cette action.'))await mutate(()=>catalogAction('service_archive',{id:button.dataset.id}),'Prestation désactivée.');return;}
  if(action==='archive-rate'){if(confirm('Désactiver ce tarif fournisseur ?'))await mutate(()=>catalogAction('rate_archive',{id:button.dataset.id}),'Tarif désactivé.');return;}
  if(action==='pay'){if(confirm('Confirmer que ce fournisseur a bien été payé ?'))await paySupplier(button.dataset.id);return;}
  if(action==='supplier-back'||action==='supplier-next'){await supplierWizardMove(action==='supplier-next'?1:-1);return;}
  if(action==='format-back'||action==='format-next'){await formatWizardMove(action==='format-next'?1:-1);return;}
  if(action==='draft-add-cap'){saveDraftVisible(button.dataset.kind);addDraftCapability(button.dataset.kind);return;}
  if(action==='draft-remove-cap'){saveDraftVisible(button.dataset.kind);draftFor(button.dataset.kind).capabilities.splice(Number(button.dataset.index),1);render();return;}
  if(action==='draft-add-rate'){saveDraftVisible(button.dataset.kind);draftFor(button.dataset.kind).capabilities[Number(button.dataset.cap)]?.rates.push(newDraftRate());render();return;}
  if(action==='draft-remove-rate'){saveDraftVisible(button.dataset.kind);draftFor(button.dataset.kind).capabilities[Number(button.dataset.cap)]?.rates.splice(Number(button.dataset.rate),1);render();return;}
  if(action==='draft-add-card'){saveFormatDraftVisible();formatDraft.cards.push({label:'',description:'',imageUrl:''});render();return;}
  if(action==='draft-remove-card'){saveFormatDraftVisible();formatDraft.cards.splice(Number(button.dataset.index),1);render();return;}
}

async function handleSubmit(event){
  const form=event.target.closest('[data-p120-form]');if(!form)return;event.preventDefault();const kind=form.dataset.p120Form,fd=new FormData(form);
  if(kind==='supplier-info'){
    const supplierId=fd.get('supplierId');
    await mutate(async()=>{await postCatalog('supplier/save',{id:supplierId,name:fd.get('name'),email:fd.get('email'),legalName:fd.get('legalName'),notes:fd.get('notes'),active:true});await productionAction('production_supplier_settings_save',{supplierId,paymentMethod:fd.get('paymentMethod'),paymentUrl:fd.get('paymentUrl'),paymentTermsDays:Number(fd.get('paymentTermsDays')||0),billingEmail:fd.get('billingEmail'),paymentNotes:fd.get('paymentNotes')});},'Fournisseur enregistré.');return;
  }
  if(kind==='service-add'){
    const supplierId=fd.get('fixedSupplierId')||fd.get('supplierId'),formatId=fd.get('fixedFormatId')||fd.get('formatId');
    await mutate(async()=>{const result=await catalogAction('service_save',{cityId:fd.get('cityId'),supplierId,formatId,preparationUrl:fd.get('preparationUrl'),notes:'',active:true});drawer.sub='';drawer.rateServiceId=result.savedId||'';},'Prestation ajoutée.');return;
  }
  if(kind==='rate-add'){
    await mutate(()=>catalogAction('rate_save',{serviceId:fd.get('serviceId'),unitCode:fd.get('unitCode')||'custom',durationMinutes:Number(fd.get('durationMinutes')),netCents:Math.round(Number(fd.get('net')||0)*100),vatRateBps:Math.round(Number(fd.get('vat')||20)*100),active:true,publicOrder:100}),'Tarif fournisseur ajouté.');drawer.rateServiceId='';return;
  }
  if(kind==='prep-card'){
    await mutate(()=>productionAction('production_preparation_card_save',{id:fd.get('id'),formatId:fd.get('formatId'),label:fd.get('label'),description:fd.get('description'),imageUrl:fd.get('imageUrl'),publicOrder:Number(fd.get('publicOrder')||100),active:true}),'Card de préparation enregistrée.');drawer.cardEdit=null;return;
  }
  if(kind==='format-info'){
    const f=formatById(fd.get('formatId'));
    await mutate(()=>postCatalog('format/save',{id:f.id,name:fd.get('name'),conceptId:fd.get('conceptId'),shootMinutes:Number(fd.get('shootMinutes')),totalMinutes:Number(fd.get('totalMinutes')),description:fd.get('description'),imageUrl:fd.get('imageUrl'),publicOrder:Number(f.publicOrder||100),active:f.active!==false}),'Format enregistré.');return;
  }
  if(kind==='passage-assign'){
    const rate=rateById(fd.get('rateId')),service=rate?serviceById(rate.serviceId):null;if(!rate||!service)return toast('Sélectionnez un tarif valide.',true);
    await mutate(()=>productionAction('production_order_supplier_assign',{orderId:fd.get('orderId'),supplierRateId:rate.id,serviceId:service.id,supplierId:service.supplierId,cityId:service.cityId,formatId:service.formatId}),'Passage rattaché au fournisseur.');closeDrawer(false);return;
  }
}

function handleInput(event){if(event.target.id==='p120Search'){searchText=event.target.value;window.clearTimeout(handleInput.timer);handleInput.timer=window.setTimeout(render,120);}}
async function handleChange(event){const input=event.target.closest('[data-p120-upload-for]');if(!input||!input.files?.[0])return;const target=document.getElementById(input.dataset.p120UploadFor);try{toast('Import du visuel…');const url=await uploadAsset(input.files[0]);if(target){target.value=url;target.dispatchEvent(new Event('input',{bubbles:true}));}toast('Visuel importé.');}catch(error){toast(errorText(error.message),true);}}

async function supplierWizardMove(delta){const d=supplierDraft;if(!d)return;saveSupplierDraftVisible();if(delta<0){d.step=Math.max(0,d.step-1);render();return;}const error=validateSupplierDraftStep(d);if(error)return toast(error,true);if(d.step<3){d.step+=1;render();return;}await createSupplierDraft(d);}
async function formatWizardMove(delta){const d=formatDraft;if(!d)return;saveFormatDraftVisible();if(delta<0){d.step=Math.max(0,d.step-1);render();return;}const error=validateFormatDraftStep(d);if(error)return toast(error,true);if(d.step<4){d.step+=1;render();return;}await createFormatDraft(d);}

function saveSupplierDraftVisible(){if(!supplierDraft)return;if(supplierDraft.step===0){supplierDraft.name=value('p120DraftSupplierName');supplierDraft.email=value('p120DraftSupplierEmail');supplierDraft.legalName=value('p120DraftSupplierLegal');supplierDraft.paymentMethod=value('p120DraftSupplierMethod')||'bank_transfer';supplierDraft.paymentTermsDays=Number(value('p120DraftSupplierTerms')||0);supplierDraft.paymentUrl=value('p120DraftSupplierPaymentUrl');}if(supplierDraft.step===2)saveDraftRates(supplierDraft);}
function saveFormatDraftVisible(){if(!formatDraft)return;if(formatDraft.step===0){formatDraft.name=value('p120DraftFormatName');formatDraft.conceptId=value('p120DraftFormatConcept');formatDraft.newConcept=value('p120DraftFormatNewConcept');formatDraft.shootMinutes=Number(value('p120DraftFormatShoot')||0);formatDraft.totalMinutes=Number(value('p120DraftFormatTotal')||0);formatDraft.imageUrl=value('p120DraftFormatImage');formatDraft.description=value('p120DraftFormatDescription');}if(formatDraft.step===1){document.querySelectorAll('[data-draft-card-label]').forEach(input=>{const i=Number(input.dataset.draftCardLabel);if(formatDraft.cards[i])formatDraft.cards[i].label=input.value.trim();});document.querySelectorAll('[data-draft-card-description]').forEach(input=>{const i=Number(input.dataset.draftCardDescription);if(formatDraft.cards[i])formatDraft.cards[i].description=input.value.trim();});document.querySelectorAll('[data-draft-card-image]').forEach(input=>{const i=Number(input.dataset.draftCardImage);if(formatDraft.cards[i])formatDraft.cards[i].imageUrl=input.value.trim();});}if(formatDraft.step===2)document.querySelectorAll('[data-draft-cap-prep]').forEach(input=>{const i=Number(input.dataset.draftCapPrep);if(formatDraft.capabilities[i])formatDraft.capabilities[i].preparationUrl=input.value.trim();});if(formatDraft.step===3)saveDraftRates(formatDraft);}
function saveDraftVisible(kind){if(kind==='supplier')saveSupplierDraftVisible();else saveFormatDraftVisible();}
function saveDraftRates(d){document.querySelectorAll('[data-draft-rate-duration]').forEach(input=>{const [ci,ri]=input.dataset.draftRateDuration.split(':').map(Number);if(d.capabilities[ci]?.rates[ri])d.capabilities[ci].rates[ri].durationMinutes=Number(input.value||0);});document.querySelectorAll('[data-draft-rate-net]').forEach(input=>{const [ci,ri]=input.dataset.draftRateNet.split(':').map(Number);if(d.capabilities[ci]?.rates[ri])d.capabilities[ci].rates[ri].netCents=Math.round(Number(input.value||0)*100);});}

function addDraftCapability(kind){const d=draftFor(kind),cityId=value('p120DraftCapCity');if(!cityId)return toast('Choisissez une ville.',true);if(kind==='supplier'){const formatId=value('p120DraftCapFormat');if(!formatId)return toast('Choisissez un format.',true);if(d.capabilities.some(c=>c.cityId===cityId&&c.formatId===formatId))return toast('Cette capacité est déjà ajoutée.',true);d.capabilities.push({cityId,formatId,rates:[newDraftRate()]});}else{const supplierId=value('p120DraftCapSupplier');if(!supplierId)return toast('Choisissez un fournisseur.',true);if(d.capabilities.some(c=>c.cityId===cityId&&c.supplierId===supplierId))return toast('Cette affectation existe déjà.',true);d.capabilities.push({cityId,supplierId,preparationUrl:'',rates:[newDraftRate()]});}render();}
function draftFor(kind){return kind==='supplier'?supplierDraft:formatDraft;}
function newDraftRate(){return{durationMinutes:120,netCents:0,vatRateBps:2000};}
function newSupplierDraft(){return{step:0,name:'',email:'',legalName:'',paymentMethod:'bank_transfer',paymentTermsDays:0,paymentUrl:'',capabilities:[]};}
function newFormatDraft(){return{step:0,name:'',conceptId:(ctx?.concepts||[]).find(c=>c.active!==false)?.id||'__new',newConcept:'',shootMinutes:60,totalMinutes:120,imageUrl:'',description:'',cards:[],capabilities:[]};}

function validateSupplierDraftStep(d){if(d.step===0&&!d.name.trim())return'Renseignez le nom du fournisseur.';if(d.step===1&&!d.capabilities.length)return'Ajoutez au moins une ville et un format compatible.';if(d.step===2&&d.capabilities.some(c=>c.rates.some(r=>!r.durationMinutes||r.netCents<=0)))return'Chaque tarif ajouté doit avoir une durée et un coût HT.';return'';}
function validateFormatDraftStep(d){if(d.step===0){if(!d.name.trim())return'Renseignez le nom du format.';if(!d.shootMinutes||!d.totalMinutes)return'Renseignez les deux durées.';if(d.totalMinutes<d.shootMinutes)return'La durée totale allouée doit être supérieure ou égale au tournage.';if(d.conceptId==='__new'&&!d.newConcept.trim())return'Renseignez le nouveau concept.';}if(d.step===1&&d.cards.some(c=>!c.label.trim()))return'Nommez chaque card de préparation ou retirez la ligne vide.';if(d.step===3&&d.capabilities.some(c=>c.rates.some(r=>!r.durationMinutes||r.netCents<=0)))return'Chaque tarif ajouté doit avoir une durée et un coût HT.';return'';}

async function createSupplierDraft(d){try{setWizardBusy(true);const saved=await postCatalog('supplier/save',{name:d.name,email:d.email,legalName:d.legalName||d.name,notes:'',active:true});const supplierId=saved.savedId;if(!supplierId)throw Error('supplier_save_failed');await productionAction('production_supplier_settings_save',{supplierId,paymentMethod:d.paymentMethod,paymentUrl:d.paymentUrl,paymentTermsDays:d.paymentTermsDays,billingEmail:d.email,paymentNotes:''});for(const cap of d.capabilities){const service=await catalogAction('service_save',{cityId:cap.cityId,supplierId,formatId:cap.formatId,preparationUrl:'',notes:'',active:true});for(let i=0;i<cap.rates.length;i++){const r=cap.rates[i];await catalogAction('rate_save',{serviceId:service.savedId,unitCode:'custom',durationMinutes:r.durationMinutes,netCents:r.netCents,vatRateBps:r.vatRateBps,active:true,publicOrder:(i+1)*10});}}supplierDraft=null;await reload('Fournisseur créé.');drawer={type:'supplier',id:supplierId,tab:'overview'};render();}catch(error){toast(errorText(error.message),true);setWizardBusy(false);}}
async function createFormatDraft(d){try{setWizardBusy(true);const payload={name:d.name,conceptId:d.conceptId==='__new'?'':d.conceptId,concept:d.conceptId==='__new'?d.newConcept:'',shootMinutes:d.shootMinutes,totalMinutes:d.totalMinutes,description:d.description,imageUrl:d.imageUrl,publicOrder:100,active:true};const saved=await postCatalog('format/save',payload);const formatId=saved.savedId;if(!formatId)throw Error('format_save_failed');for(let i=0;i<d.cards.length;i++){const c=d.cards[i];await productionAction('production_preparation_card_save',{formatId,label:c.label,description:c.description,imageUrl:c.imageUrl,publicOrder:(i+1)*10,active:true});}for(const cap of d.capabilities){const service=await catalogAction('service_save',{cityId:cap.cityId,supplierId:cap.supplierId,formatId,preparationUrl:cap.preparationUrl||'',notes:'',active:true});for(let i=0;i<cap.rates.length;i++){const r=cap.rates[i];await catalogAction('rate_save',{serviceId:service.savedId,unitCode:'custom',durationMinutes:r.durationMinutes,netCents:r.netCents,vatRateBps:r.vatRateBps,active:true,publicOrder:(i+1)*10});}}formatDraft=null;await reload('Format créé et affectations enregistrées.');drawer={type:'format',id:formatId,tab:'cards'};render();}catch(error){toast(errorText(error.message),true);setWizardBusy(false);}}
function setWizardBusy(busy){document.querySelectorAll('.p120-drawer-foot button').forEach(button=>button.disabled=busy);}

async function mutate(fn,success){try{await fn();await reload(success,false);render();}catch(error){toast(errorText(error.message),true);}}
async function reload(success='',rerender=true){ctx=await productionAction('production_context');if(success)toast(success);if(rerender)render();}
async function paySupplier(paymentId){try{await jsonFetch('/api/admin/supplier-payment',{method:'POST',body:JSON.stringify({paymentId})});await reload('Paiement fournisseur marqué comme payé.');}catch(error){toast(errorText(error.message),true);}}

async function postCatalog(path,payload){return jsonFetch(API+path,{method:'POST',body:JSON.stringify(payload)});}
async function catalogAction(action,payload={}){return postCatalog('family/save',{catalogAction:action,...payload});}
async function productionAction(action,payload={}){return postCatalog('family/save',{catalogAction:action,...payload});}
async function jsonFetch(url,options={},retry=true){const headers=new Headers(options.headers||{});headers.set('Accept','application/json');if(options.body&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');const csrf=sessionStorage.getItem('neptune_csrf')||'';if(csrf)headers.set('X-CSRF-Token',csrf);const response=await fetch(url,{...options,headers,credentials:'same-origin',cache:'no-store'});const data=await response.json().catch(()=>({}));if(response.status===403&&data.error==='csrf_failed'&&retry){const auth=await fetch('/api/auth/status',{credentials:'same-origin',cache:'no-store'}).then(r=>r.json()).catch(()=>({}));if(auth.csrfToken){sessionStorage.setItem('neptune_csrf',auth.csrfToken);return jsonFetch(url,options,false);}}if(!response.ok)throw Error(data.error||`http_${response.status}`);return data;}
async function uploadAsset(file){const fd=new FormData();fd.append('file',file);const headers=new Headers();const csrf=sessionStorage.getItem('neptune_csrf')||'';if(csrf)headers.set('X-CSRF-Token',csrf);const response=await fetch(API+'asset/upload',{method:'POST',body:fd,headers,credentials:'same-origin'}),data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'upload_failed');return data.url;}

function metrics(){const suppliers=filteredSuppliers().filter(s=>s.active!==false),services=filteredServices(),cities=new Set(services.map(s=>s.cityId)),formats=new Set(services.map(s=>s.formatId)),passages=filteredPassages();return{suppliers:suppliers.length,cities:cities.size,formats:formats.size,upcoming:passages.filter(p=>p.supplierId&&isUpcoming(p)).length,due:passages.filter(p=>p.supplierPaymentStatus==='due').reduce((n,p)=>n+Number(p.supplierPaymentAmount||p.supplierGrossCents||0),0)};}
function filteredSuppliers(){const q=normal(searchText);return(ctx.suppliers||[]).filter(s=>{const services=servicesForSupplier(s.id).filter(cityMatch);if(cityFilter&&!services.length)return false;if(!q)return true;return normal([s.name,s.email,s.legalName,...services.map(x=>`${x.cityName} ${x.formatName}`)].join(' ')).includes(q);});}
function filteredServices(){const q=normal(searchText);return(ctx.services||[]).filter(s=>s.active!==false&&cityMatch(s)&&(!q||normal(`${s.cityName} ${s.supplierName} ${s.formatName} ${s.notes||''}`).includes(q)));}
function filteredFormats(){const q=normal(searchText);return(ctx.formats||[]).filter(f=>{const services=(ctx.services||[]).filter(s=>s.active!==false&&s.formatId===f.id&&cityMatch(s));if(cityFilter&&!services.length)return false;return !q||normal(`${f.name} ${f.concept||''} ${cardsForFormat(f.id).map(c=>c.label).join(' ')} ${services.map(s=>s.supplierName).join(' ')}`).includes(q);});}
function filteredPassages(){const q=normal(searchText);return(ctx.passages||[]).filter(p=>(!cityFilter||p.cityId===cityFilter)&&(!q||normal(`${p.fullName||''} ${p.company||''} ${p.email||''} ${p.format||''} ${p.supplierName||''} ${p.cityName||''}`).includes(q)));}
function passagesForFilter(){const rows=filteredPassages();if(passageFilter==='all')return rows;if(passageFilter==='due')return rows.filter(p=>p.supplierPaymentStatus==='due');if(passageFilter==='paid')return rows.filter(p=>p.supplierPaymentStatus==='paid');if(passageFilter==='filmed')return rows.filter(p=>['filmed','videos_pending','videos_received','editing','approval','delivered','completed'].includes(p.status));return rows.filter(isUpcoming);}
function isUpcoming(p){if(['filmed','videos_pending','videos_received','editing','approval','delivered','completed'].includes(p.status))return false;const d=new Date(p.filmingAt||'');return p.filmingAt&&!Number.isNaN(d.getTime())&&d.getTime()>=Date.now();}
function duePassages(){return(ctx.passages||[]).filter(p=>p.supplierPaymentStatus==='due'&&(!cityFilter||p.cityId===cityFilter));}
function dueTotal(){return duePassages().reduce((n,p)=>n+Number(p.supplierPaymentAmount||p.supplierGrossCents||0),0);}
function servicesForSupplier(id){return(ctx.services||[]).filter(s=>s.active!==false&&s.supplierId===id);}
function ratesForService(id){return(ctx.supplierRates||[]).filter(r=>r.active!==false&&r.serviceId===id).sort((a,b)=>Number(a.durationMinutes)-Number(b.durationMinutes));}
function cardsForFormat(id){return(ctx.preparationCards||[]).filter(c=>c.active!==false&&c.formatId===id).sort((a,b)=>Number(a.publicOrder)-Number(b.publicOrder));}
function passagesForSupplier(id){return(ctx.passages||[]).filter(p=>p.supplierId===id);}
function cityMatch(service){return!cityFilter||service.cityId===cityFilter;}
function matchingServicesForPassage(p){const exact=(ctx.services||[]).filter(s=>s.active!==false&&normal(s.formatName)===normal(p.format));return exact.length?exact:(ctx.services||[]).filter(s=>s.active!==false);}
function supplierById(id){return(ctx.suppliers||[]).find(x=>x.id===id)||null;}function formatById(id){return(ctx.formats||[]).find(x=>x.id===id)||null;}function serviceById(id){return(ctx.services||[]).find(x=>x.id===id)||null;}function rateById(id){return(ctx.supplierRates||[]).find(x=>x.id===id)||null;}function passageById(id){return(ctx.passages||[]).find(x=>x.id===id)||null;}
function supplierName(id){return supplierById(id)?.name||'Fournisseur';}function formatName(id){return formatById(id)?.name||'Format';}function cityName(id){return(ctx.cities||[]).find(x=>x.id===id)?.name||'Ville';}

function passageDrawerRow(p){return `<article class="p120-service-card"><div class="p120-service-head"><div><strong>${esc(p.fullName||p.company||p.title)}</strong><span>${p.filmingAt?dateTime(p.filmingAt):'Date à fixer'} · ${esc(p.format||'')}</span></div><span class="p120-status ${p.supplierPaymentStatus==='due'?'due':p.supplierPaymentStatus==='paid'?'paid':''}">${p.supplierPaymentStatus==='due'?'À payer':p.supplierPaymentStatus==='paid'?'Payé':'En cours'}</span></div></article>`;}
function paymentDrawerRow(p){return `<article class="p120-service-card"><div class="p120-service-head"><div><strong>${esc(p.fullName||p.company||p.title)}</strong><span>${esc(p.rateLabel||'Tarif fournisseur')} · ${p.filmingAt?dateOnly(p.filmingAt):''}</span></div><strong>${money(p.supplierPaymentAmount||p.supplierGrossCents)}</strong></div><div class="p120-inline-actions"><span class="p120-status ${p.supplierPaymentStatus==='paid'?'paid':'due'}">${p.supplierPaymentStatus==='paid'?'Payé':'À payer'}</span>${p.supplierPaymentStatus==='due'?`<button class="p120-btn" type="button" data-p120="pay" data-id="${esc(p.supplierPaymentId)}">Marquer payé</button>`:''}</div></article>`;}
function drawerTab(id,label,current){return`<button class="p120-subtab ${id===current?'active':''}" type="button" data-p120="drawer-tab" data-tab="${id}">${label}</button>`;}
function kpi(value,label,detail){return`<article class="p120-kpi"><small>${esc(label)}</small><strong>${esc(value)}</strong><span>${esc(detail)}</span></article>`;}
function alertCard(icon,count,label,detail){return`<article class="p120-alert"><i>${esc(icon)}</i><div><strong>${Number(count)||0} · ${esc(label)}</strong><span>${esc(detail)}</span></div></article>`;}
function empty(text){return`<div class="p120-empty"><div><strong>Rien à afficher.</strong><p>${esc(text)}</p></div></div>`;}
function image(src,alt=''){return`<img src="${esc(src||'/assets/posters/studio-wide.webp')}" alt="${esc(alt)}" loading="lazy">`;}
function prepImage(c){if(c.imageBase64)return`<img data-p120-b64="${esc(c.imageBase64)}" alt="${esc(c.label)}">`;return image(c.image||c.imageUrl,c.label);}
async function hydrateB64(root){for(const img of root.querySelectorAll('[data-p120-b64]'))try{const text=await fetch(img.dataset.p120B64).then(r=>r.text());img.src='data:image/webp;base64,'+text.trim();}catch{img.src='/assets/posters/studio-wide.webp';}}
function durationOptions(selected){return(ctx.durationOptions||[]).map(o=>`<option value="${o.minutes}" ${Number(selected)===Number(o.minutes)?'selected':''}>${esc(o.label)}</option>`).join('');}
function durationLabel(minutes){const m=Number(minutes||0);if(!m)return'—';const h=Math.floor(m/60),r=m%60;return h&&r?`${h} h ${r}`:h?`${h} h`:`${r} min`;}
function paymentOptions(selected){return[['bank_transfer','Virement bancaire'],['payment_link','Lien de règlement'],['invoice','Facture / échéance'],['other','Autre']].map(([v,l])=>`<option value="${v}" ${selected===v?'selected':''}>${l}</option>`).join('');}
function paymentMethodLabel(value){return({bank_transfer:'Virement bancaire',payment_link:'Lien de règlement',invoice:'Facture / échéance',other:'Autre'})[value]||'Virement bancaire';}
function money(cents,currency='eur'){return new Intl.NumberFormat('fr-FR',{style:'currency',currency:String(currency||'eur').toUpperCase(),maximumFractionDigits:2}).format(Number(cents||0)/100);}
function dateTime(value){const d=new Date(value);return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Paris'}).format(d);}
function dateOnly(value){const d=new Date(value);return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeZone:'Europe/Paris'}).format(d);}
function unique(items){return[...new Set(items.filter(Boolean))];}
function normal(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/gu,'').toLowerCase().replace(/\s+/gu,' ').trim();}
function value(id){return document.getElementById(id)?.value?.trim?.()||'';}
function esc(value){return String(value??'').replace(/[&<>"']/gu,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[c]));}
function closeDrawer(rerender=true){drawer=null;supplierDraft=null;formatDraft=null;if(rerender&&active())render();}
function toast(text,error=false){document.querySelector('.p120-toast')?.remove();const el=document.createElement('div');el.className=`p120-toast ${error?'error':''}`;el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3200);}
function errorText(value){return({unauthorized:'Session Studio expirée.',csrf_failed:'Session Studio à renouveler.',service_already_exists:'Cette ville et ce format sont déjà rattachés à ce fournisseur.',rate_used_by_offer:'Ce tarif est utilisé par une offre client et ne peut pas être retiré.',service_used_by_active_offer:'Cette prestation est utilisée par une offre client active.',preparation_card_already_exists:'Une card porte déjà ce nom pour ce format.',total_duration_shorter_than_shoot:'La durée totale ne peut pas être plus courte que le tournage.',supplier_rate_inactive:'Ce tarif fournisseur n’est plus actif.',supplier_rate_service_mismatch:'Le tarif ne correspond pas à la prestation sélectionnée.'}[value]||value||'Une erreur est survenue.');}
function repairFinanceCopy(){for(const p of document.querySelectorAll('#content .page-intro p'))if(p.textContent.includes('dette fournisseur de 720'))p.textContent='Le règlement fournisseur reprend le coût figé sur chaque passage : fournisseur, durée, HT, TVA et TTC restent traçables même si le tarif évolue ensuite.';}
